package api

import (
	"fmt"
	"go/format"
	"sort"
	"strings"

	"go.putnami.dev/errors"
	clientcontract "go.putnami.dev/protocol/clientcontract"
)

// ClientGenOptions configure typed Go client generation.
type ClientGenOptions struct {
	// PackageName is the Go package the generated file is emitted into. Required.
	PackageName string
	// ClientName is the generated struct name (default "Client").
	ClientName string
	// BaseURLDefault is an optional default BaseURL for the generated NewClient helper.
	BaseURLDefault string
	// Design, when present, embeds exact operation identity into the generated
	// client descriptor and every outgoing request, plus the producer project
	// and feature of each operation whose contract names one.
	Design *ClientDesignOptions
	// OmitOperations names operations, by operationId, that the generated client
	// leaves out instead of failing: the escape for an operation this emitter
	// cannot represent yet, so one operation does not cost the whole client. The
	// client's doc comment names every operation left out. A name the contract
	// does not declare fails generation, and so does every other operation the
	// emitter cannot represent. Empty by default: every declared operation is
	// emitted or generation fails.
	OmitOperations []string
}

// ClientDesignOptions carry the build-time identity embedded into a generated
// client. Producer attribution is per operation and comes from the contract:
// each operation's x-putnami-client producer. One generated client routinely
// spans several producer features, and an operation whose contract names no
// producer is emitted unattributed instead of inheriting a neighbor's feature.
type ClientDesignOptions struct {
	// SpecHash pins the contract the client was generated from. Defaulted from
	// the spec IR when empty.
	SpecHash string
}

// renderClient assembles the final source file from the registered struct
// definitions and the method set. [GenerateClientFromIR] is the supported
// pipeline that calls in here so the header, conditional import block, client
// struct, and emission order stay identical regardless of input.
func renderClient(g *clientGen, opts ClientGenOptions, clientName string, methods []methodEmit) (string, error) {
	// --- Build method bodies into a separate buffer so we can track which imports
	// are actually referenced before we emit the import block. ---
	var methodsBuf strings.Builder
	designName := ""
	if opts.Design != nil {
		designName = clientName + "Design"
	}
	for _, m := range methods {
		emitMethod(&methodsBuf, g, m, designName)
	}

	// --- Header + import block (conditional on tracked imports). ---
	var b strings.Builder
	b.WriteString("// Code generated by go.putnami.dev/api. DO NOT EDIT.\n\n")
	fmt.Fprintf(&b, "package %s\n\n", opts.PackageName)
	emitImports(&b, g.imports)
	if opts.Design != nil {
		emitClientDesign(&b, designName, clientName, *opts.Design, methods)
	}

	// --- Client struct + constructor ---
	fmt.Fprintf(&b, "// %s is a typed client for the discovered API endpoints.\n", clientName)
	emitOmittedOperations(&b, g.omitted)
	fmt.Fprintf(&b, "type %s struct {\n\ttransport *client.Client\n}\n\n", clientName)

	fmt.Fprintf(&b, "// New%s wraps a client.Client with typed RPC methods.\n", clientName)
	fmt.Fprintf(&b, "func New%s(c *client.Client) *%s {\n\treturn &%s{transport: c}\n}\n\n", clientName, clientName, clientName)

	if opts.BaseURLDefault != "" {
		fmt.Fprintf(&b, "// DefaultBaseURL is the BaseURL recommended for this generated client.\n")
		fmt.Fprintf(&b, "const DefaultBaseURL = %q\n\n", opts.BaseURLDefault)
	}

	// --- Type definitions (deterministic order: registration order). ---
	for _, name := range g.structOrder {
		b.WriteString(g.structDefs[name])
		b.WriteString("\n")
	}

	// --- Method bodies ---
	b.WriteString(methodsBuf.String())

	// Emit gofmt-clean source. A format failure is returned as an error and
	// nothing is written.
	formatted, err := format.Source([]byte(b.String()))
	if err != nil {
		return "", errors.Newf(CodeClientGenFormat, "api: format generated client: %v", err)
	}
	return string(formatted), nil
}

// emitImports renders the conditional import block based on the tracked usage set.
func emitImports(b *strings.Builder, imports map[string]bool) {
	if len(imports) == 0 {
		return
	}
	keys := make([]string, 0, len(imports))
	for k := range imports {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	// Group stdlib imports above the framework import.
	std := keys[:0:0]
	frame := keys[:0:0]
	for _, k := range keys {
		if strings.HasPrefix(k, "go.putnami.dev/") {
			frame = append(frame, k)
		} else {
			std = append(std, k)
		}
	}

	b.WriteString("import (\n")
	for _, k := range std {
		fmt.Fprintf(b, "\t%q\n", k)
	}
	if len(std) > 0 && len(frame) > 0 {
		b.WriteString("\n")
	}
	for _, k := range frame {
		fmt.Fprintf(b, "\t%q\n", k)
	}
	b.WriteString(")\n\n")
}

// methodEmit is the transport-neutral input to emitMethod. The OpenAPI IR path
// ([GenerateClientFromIR]) builds this shape, so the method-body emission —
// path substitution, query string, body marshaling, response decoding, and
// import tracking — is shared across every operation.
type methodEmit struct {
	ClientName  string
	Name        string
	InputName   string
	OutputRef   string // empty for a void return
	HTTPMethod  string
	Path        string
	Description string
	OperationID string
	// Producer is the operation's producer attribution from its contract, or
	// nil when the contract names none.
	Producer  *clientcontract.OperationProducer
	HasParams bool
	HasQuery  bool
	HasBody   bool
	// Params and Query are the path/query fields used to build URL substitution
	// and the query string. Only consulted when HasParams / HasQuery is set.
	Params []fieldEntry
	Query  []fieldEntry
}

func emitMethod(b *strings.Builder, g *clientGen, m methodEmit, designName string) {
	clientName, methodName, inputName, outputRef := m.ClientName, m.Name, m.InputName, m.OutputRef
	if m.Description != "" {
		fmt.Fprintf(b, "// %s — %s\n", methodName, m.Description)
	}
	fmt.Fprintf(b, "// Calls %s %s\n", m.HTTPMethod, m.Path)

	if outputRef == "" {
		fmt.Fprintf(b, "func (c *%s) %s(ctx context.Context, in %s) error {\n", clientName, methodName, inputName)
	} else {
		fmt.Fprintf(b, "func (c *%s) %s(ctx context.Context, in %s) (*%s, error) {\n", clientName, methodName, inputName, outputRef)
	}

	// Path substitution.
	fmt.Fprintf(b, "\tpath := %q\n", m.Path)
	if m.HasParams {
		g.imports["fmt"] = true
		g.imports["strings"] = true
		for _, p := range m.Params {
			catchAllToken := "{" + p.JSONName + "...}"
			valueExpr := clientFieldValueExpr("in.Params", p)
			if strings.Contains(m.Path, catchAllToken) {
				// Catch-all param: substitute verbatim. The captured value is a
				// multi-segment path; per-segment escaping is the caller's job.
				fmt.Fprintf(b, "\tpath = strings.Replace(path, %q, fmt.Sprint(%s), 1)\n",
					catchAllToken, valueExpr)
				continue
			}
			g.imports["net/url"] = true
			fmt.Fprintf(b, "\tpath = strings.Replace(path, %q, url.PathEscape(fmt.Sprint(%s)), 1)\n",
				"{"+p.JSONName+"}", valueExpr)
		}
	}

	// Query string.
	if m.HasQuery {
		g.imports["fmt"] = true
		g.imports["net/url"] = true
		b.WriteString("\tquery := url.Values{}\n")
		for _, q := range m.Query {
			valueExpr := clientFieldValueExpr("in.Query", q)
			if strings.HasPrefix(q.GoTypeName, "[]") {
				// Array query param: emit one encoded value per element with
				// query.Add, not fmt.Sprint of the whole slice ("[a b]"), which
				// the server rejects. A nil/empty slice ranges zero times, so this
				// also handles the optional case.
				fmt.Fprintf(b, "\tfor _, v := range %s {\n", valueExpr)
				fmt.Fprintf(b, "\t\tquery.Add(%q, fmt.Sprint(v))\n", q.JSONName)
				b.WriteString("\t}\n")
				continue
			}
			if q.Optional {
				if check := clientFieldPresentExpr("in.Query", q); check != "" {
					fmt.Fprintf(b, "\tif %s {\n", check)
					fmt.Fprintf(b, "\t\tquery.Set(%q, fmt.Sprint(%s))\n", q.JSONName, valueExpr)
					b.WriteString("\t}\n")
					continue
				}
			}
			fmt.Fprintf(b, "\tquery.Set(%q, fmt.Sprint(%s))\n", q.JSONName, valueExpr)
		}
		b.WriteString("\tif encoded := query.Encode(); encoded != \"\" {\n")
		b.WriteString("\t\tpath = path + \"?\" + encoded\n")
		b.WriteString("\t}\n")
	}

	// Body marshaling.
	if m.HasBody {
		g.imports["encoding/json"] = true
		b.WriteString("\tbodyBytes, err := json.Marshal(in.Body)\n")
		b.WriteString("\tif err != nil {\n")
		if outputRef == "" {
			g.imports["fmt"] = true
			b.WriteString("\t\treturn fmt.Errorf(\"marshal request body: %w\", err)\n")
		} else {
			g.imports["fmt"] = true
			b.WriteString("\t\treturn nil, fmt.Errorf(\"marshal request body: %w\", err)\n")
		}
		b.WriteString("\t}\n")
	}

	// Build request.
	if designName != "" {
		fmt.Fprintf(b, "\treq := &client.Request{Method: %q, Path: path, FeatureTrace: %s.Trace(%q)}\n", m.HTTPMethod, designName, m.OperationID)
	} else {
		fmt.Fprintf(b, "\treq := &client.Request{Method: %q, Path: path}\n", m.HTTPMethod)
	}
	if m.HasBody {
		b.WriteString("\treq.Body = bodyBytes\n")
		b.WriteString("\treq.SetHeader(\"Content-Type\", \"application/json\")\n")
	}

	b.WriteString("\tresp, err := c.transport.Do(ctx, req)\n")
	b.WriteString("\tif err != nil {\n")
	if outputRef == "" {
		b.WriteString("\t\treturn err\n")
	} else {
		b.WriteString("\t\treturn nil, err\n")
	}
	b.WriteString("\t}\n")

	g.imports["fmt"] = true
	b.WriteString("\tif !resp.IsSuccess() {\n")
	if outputRef == "" {
		b.WriteString("\t\treturn fmt.Errorf(\"server returned %d: %s\", resp.StatusCode, string(resp.Body))\n")
	} else {
		b.WriteString("\t\treturn nil, fmt.Errorf(\"server returned %d: %s\", resp.StatusCode, string(resp.Body))\n")
	}
	b.WriteString("\t}\n")

	if outputRef == "" {
		b.WriteString("\treturn nil\n")
		b.WriteString("}\n\n")
		return
	}

	g.imports["bytes"] = true
	g.imports["encoding/json"] = true
	fmt.Fprintf(b, "\tvar out %s\n", outputRef)
	b.WriteString("\tif len(resp.Body) > 0 {\n")
	b.WriteString("\t\tif err := json.NewDecoder(bytes.NewReader(resp.Body)).Decode(&out); err != nil {\n")
	b.WriteString("\t\t\treturn nil, fmt.Errorf(\"decode response: %w\", err)\n")
	b.WriteString("\t\t}\n")
	b.WriteString("\t}\n")
	b.WriteString("\treturn &out, nil\n")
	b.WriteString("}\n\n")
}

// emitClientDesign renders the client descriptor: the exact API contract plus,
// per operation, the producer that owns it. Operations follow the method
// emission order (itself derived from the deterministic spec walk), and an
// operation whose contract names no producer is emitted without producer
// fields so its lineage stays visibly unknown.
func emitClientDesign(b *strings.Builder, designName, clientName string, design ClientDesignOptions, methods []methodEmit) {
	fmt.Fprintf(b, "// %s identifies the exact API contract and the producer feature of each operation.\n", designName)
	fmt.Fprintf(b, "var %s = client.GeneratedClientDesign{\n", designName)
	b.WriteString("\tLanguage: \"go\",\n")
	fmt.Fprintf(b, "\tClient:   %q,\n", clientName)
	if design.SpecHash != "" {
		fmt.Fprintf(b, "\tSpecHash: %q,\n", design.SpecHash)
	}
	b.WriteString("\tOperations: []client.GeneratedClientOperation{\n")
	for _, method := range methods {
		fmt.Fprintf(b, "\t\t{OperationID: %q, Method: %q, Path: %q", method.OperationID, method.HTTPMethod, method.Path)
		if producer := method.Producer; producer != nil {
			fmt.Fprintf(b, ", ProducerProject: %q, ProducerFeature: %q", producer.Project, producer.Feature)
		}
		b.WriteString("},\n")
	}
	b.WriteString("\t},\n}\n\n")
}

func clientFieldValueExpr(sectionExpr string, f fieldEntry) string {
	expr := sectionExpr + "." + f.GoFieldName
	if strings.HasPrefix(f.GoTypeName, "*") {
		return "*" + expr
	}
	return expr
}

func clientFieldPresentExpr(sectionExpr string, f fieldEntry) string {
	expr := sectionExpr + "." + f.GoFieldName
	switch {
	case strings.HasPrefix(f.GoTypeName, "*"),
		strings.HasPrefix(f.GoTypeName, "[]"),
		strings.HasPrefix(f.GoTypeName, "map["),
		f.GoTypeName == "any":
		return expr + " != nil"
	default:
		return ""
	}
}

// --- Code-gen helpers ---

type clientGen struct {
	opts        ClientGenOptions
	clientName  string
	structDefs  map[string]string
	structOrder []string
	// imports tracks the set of import paths the generated file actually references.
	// Always includes "context" and "go.putnami.dev/client"; method emission adds the
	// rest based on what each method body needs.
	imports map[string]bool
	// omitted is what ClientGenOptions.OmitOperations left out, in contract
	// order. The client's doc comment names each one.
	omitted []MethodIR
}

type fieldEntry struct {
	JSONName    string
	GoFieldName string
	GoTypeName  string
	Optional    bool
}

type sectionEntry struct {
	FieldName string // Go field name on the Input struct (Params / Query / Body)
	JSONName  string // JSON key on the wire (params / query / body)
	TypeName  string // Generated sub-type name
}

// declareInputStruct emits the top-level Input struct that nests the request sections.
// Empty sections are omitted so simple endpoints (no params, query, body) still produce
// a typed Input struct without spurious zero-value fields.
func (g *clientGen) declareInputStruct(name string, sections []sectionEntry) {
	if _, ok := g.structDefs[name]; ok {
		return
	}
	var b strings.Builder
	fmt.Fprintf(&b, "// %s is the request input shape for the typed client method.\n", name)
	fmt.Fprintf(&b, "// Sections (Params / Query / Body) are nested so identically-named fields\n")
	fmt.Fprintf(&b, "// across path, query, and body cannot collide.\n")
	fmt.Fprintf(&b, "type %s struct {\n", name)
	for _, s := range sections {
		fmt.Fprintf(&b, "\t%s %s `json:%q`\n", s.FieldName, s.TypeName, s.JSONName)
	}
	if len(sections) == 0 {
		b.WriteString("\t_ struct{} `json:\"-\"` // placeholder so JSON marshaling stays object-shaped\n")
	}
	b.WriteString("}\n")
	g.structDefs[name] = b.String()
	g.structOrder = append(g.structOrder, name)
}

func (g *clientGen) declareStruct(name string, fields []fieldEntry) {
	if _, ok := g.structDefs[name]; ok {
		return
	}
	var b strings.Builder
	fmt.Fprintf(&b, "// %s is a typed client message.\n", name)
	fmt.Fprintf(&b, "type %s struct {\n", name)
	for _, f := range fields {
		fmt.Fprintf(&b, "\t%s %s `json:%q`\n", f.GoFieldName, f.GoTypeName, jsonTagForField(f))
	}
	if len(fields) == 0 {
		b.WriteString("\t_ struct{} `json:\"-\"` // placeholder so JSON marshaling stays object-shaped\n")
	}
	b.WriteString("}\n")
	g.structDefs[name] = b.String()
	g.structOrder = append(g.structOrder, name)
}

func jsonTagForField(f fieldEntry) string {
	if f.Optional {
		return f.JSONName + ",omitempty"
	}
	return f.JSONName
}

func isClientHTTPMethod(method string) bool {
	switch strings.ToUpper(method) {
	case "GET", "POST", "PUT", "PATCH", "DELETE":
		return true
	default:
		return false
	}
}
